1	import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
2	import prisma from "../lib/prisma.js";
3	import jwt from "jsonwebtoken";
4	
5	const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
6	
7	// Authorization 헤더에서 토큰 추출
8	function extractToken(request: FastifyRequest): string | null {
9	  const auth = request.headers.authorization;
10	  if (!auth) return null;
11	  const match = auth.match(/^Token\s+(.+)$/i);
12	  return match ? match[1] : null;
13	}
14	
15	// 토큰 디코딩
16	function verifyToken(token: string): { id: string; username: string; email: string } {
17	  return jwt.verify(token, JWT_SECRET) as any;
18	}
19	
20	// 슬러그 생성: 소문자, 공백→하이픈, 특수문자 제거
21	function slugify(title: string): string {
22	  return title
23	    .toLowerCase()
24	    .trim()
25	    .replace(/[^\w\s-]/g, "")
26	    .replace(/[\s_]+/g, "-")
27	    .replace(/^-+|-+$/g, "");
28	}
29	
30	// 태그 정규화: 소문자, 공백 제거, 빈 값 필터링
31	function normalizeTags(tagList: (string | null | undefined)[]): string[] {
32	  if (!tagList) return [];
33	  const tags = tagList
34	    .map((t) => {
35	      if (t === null || t === undefined || t === "") return null;
36	      return t.trim().toLowerCase();
37	    })
38	    .filter((t): t is string => t !== null && t !== "");
39	  return [...new Set(tags)];
40	}
41	
42	export async function articlesRoutes(app: FastifyInstance): Promise<void> {
43	  // POST /api/articles - 아티클 생성
44	  app.post("/api/articles", async (request, reply) => {
45	    const token = extractToken(request);
46	    if (!token) {
47	      return reply.code(401).send({ errors: { token: ["is missing"] } });
48	    }
49	
50	    const { article } = (request.body as any) as { article?: any };
51	    const { title, description, body, tagList } = article || {};
52	
