import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import prisma from "../lib/prisma.js";
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";

// 토큰 추출 헬퍼
function extractToken(request: FastifyRequest): string | null {
  const auth = request.headers.authorization as string | undefined;
  if (!auth) return null;
  const match = auth.match(/^Token\s+(.+)$/i);
  return match ? match[1] : null;
}

// 토큰 검증 + 사용자 ID 추출
function verifyToken(token: string): { id: string; username: string; email: string } {
  return jwt.verify(token, JWT_SECRET) as any;
}

// 아티클 조회 헬퍼 (favoritesCount, favorited 상태 포함)
async function getArticleWithMeta(
  slug: string,
  token: string | null,
): Promise<{ article: any; favorited: boolean; favoritesCount: number } | null> {
  const article = await prisma.article.findUnique({
    where: { slug },
    include: {
      author: {
        select: { id: true, username: true, bio: true, image: true },
      },
      tags: { select: { name: true } },
    },
  });
  if (!article) return null;

  let currentUserId: string | null = null;
  if (token) {
    try {
      currentUserId = verifyToken(token).id;
    } catch {
      /* invalid token, treat as no auth */
    }
  }

  // favorited 상태 및 favoritesCount 조회
  const favResult = await prisma.$queryRaw<
    { article_id: string; user_id: string }[]
  >`SELECT article_id, user_id FROM "Favorite" WHERE article_id = ${article.id}`;

  const favoritesCount = favResult.length;
  const favorited = favResult.some((r) => r.user_id === currentUserId);

  const result = {
    title: article.title,
    slug: article.slug,
    description: article.description,
    body: article.body,
    tagList: (article.tags as Array<{ name: string }>).map((t) => t.name),
    createdAt: article.createdAt,
    updatedAt: article.updatedAt,
    favorited,
    favoritesCount,
    author: {
      username: article.author.username,
      bio: article.author.bio ?? null,
      image: article.author.image ?? null,
    },
  };

  return { article: result, favorited, favoritesCount };
}

export async function favoritesRoutes(app: FastifyInstance): Promise<void> {
  // POST /api/articles/:slug/favorite - 아티클 즐겨찾기
  app.post("/api/articles/:slug/favorite", async (request: FastifyRequest, reply: FastifyReply) => {
    const slug = (request.params as any).slug as string;
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    let currentUserId: string;
    try {
      const decoded = verifyToken(token);
      currentUserId = decoded.id;
    } catch {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    // 아티클 존재 확인
    const article = await prisma.article.findUnique({
      where: { slug },
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tags: { select: { name: true } },
      },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    // 이미 즐겨찾기한 경우 upsert
    await prisma.favorite.upsert({
      where: {
        userId_articleId: {
          userId: currentUserId,
          articleId: article.id,
        },
      },
      create: {
        userId: currentUserId,
        articleId: article.id,
      },
      update: {},
    });

    // favoritesCount 재계산
    const favResult = await prisma.$queryRaw<
      { article_id: string; user_id: string }[]
    >`SELECT article_id, user_id FROM "Favorite" WHERE article_id = ${article.id}`;

    const favoritesCount = favResult.length;
    const favorited = favResult.some((r) => r.user_id === currentUserId);

    return reply.code(200).send({
      article: {
        title: article.title,
        slug: article.slug,
        description: article.description,
        body: article.body,
        tagList: (article.tags as Array<{ name: string }>).map((t) => t.name),
        createdAt: article.createdAt,
        updatedAt: article.updatedAt,
        favorited,
        favoritesCount,
        author: {
          username: article.author.username,
          bio: article.author.bio ?? null,
          image: article.author.image ?? null,
        },
      },
    });
  });

  // DELETE /api/articles/:slug/favorite - 아티클 즐겨찾기 취소
  app.delete("/api/articles/:slug/favorite", async (request: FastifyRequest, reply: FastifyReply) => {
    const slug = (request.params as any).slug as string;
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    let currentUserId: string;
    try {
      const decoded = verifyToken(token);
      currentUserId = decoded.id;
    } catch {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    // 아티클 존재 확인
    const article = await prisma.article.findUnique({
      where: { slug },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    // 즐겨찾기 삭제
    await prisma.favorite.deleteMany({
      where: {
        userId: currentUserId,
        articleId: article.id,
      },
    });

    // favoritesCount 재계산
    const favResult = await prisma.$queryRaw<
      { article_id: string; user_id: string }[]
    >`SELECT article_id, user_id FROM "Favorite" WHERE article_id = ${article.id}`;

    const favoritesCount = favResult.length;
    const favorited = false;

    // 응답용 아티클 데이터 (저자, 태그 포함)
    const articleWithMeta = await prisma.article.findUnique({
      where: { slug },
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tags: { select: { name: true } },
      },
    });

    return reply.code(200).send({
      article: {
        title: articleWithMeta!.title,
        slug: articleWithMeta!.slug,
        description: articleWithMeta!.description,
        body: articleWithMeta!.body,
        tagList: (articleWithMeta!.tags as Array<{ name: string }>).map((t) => t.name),
        createdAt: articleWithMeta!.createdAt,
        updatedAt: articleWithMeta!.updatedAt,
        favorited,
        favoritesCount,
        author: {
          username: articleWithMeta!.author.username,
          bio: articleWithMeta!.author.bio ?? null,
          image: articleWithMeta!.author.image ?? null,
        },
      },
    });
  });
}

