          favoritedMap[row.article_id] = true;
        }
      }
    }

    // 팔로우 관계 batch 조회
    let followingMap: Record<string, boolean> = {};
    if (articles.length > 0 && followingIds.length > 0) {
      const followResults = await prisma.$queryRaw<{ user_id: string }[]>`
        SELECT follower_id as user_id FROM "Follow" WHERE follower_id = ${currentUserId} AND following_id IN (${followingIds})
      `;
